#include "postquantiquecoin/p2p/PQHandshake.h"
#include "postquantiquecoin/crypto/Hashing.h"
#include "postquantiquecoin/crypto/SecureRandom.h"
#include <algorithm>
#include <chrono>
namespace pqc::p2p { namespace { uint64_t Now(){return static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count());} std::vector<uint8_t> Derive(const std::vector<uint8_t>& ss,const std::vector<uint8_t>& transcript){ auto m=ss; m.insert(m.end(),transcript.begin(),transcript.end()); return pqc::Hashing::Kmac256(ss,m,"PQC_P2P_SESSION_V1",32);} } PQHandshakeState PQHandshake::CreateClientHello(pqc::PQCryptoProvider& p){ auto kp=p.GenerateKemKeyPair(); PQHandshakeState s; s.ephemeralKemPublicKey=kp.publicKey; s.ephemeralKemPrivateKey=kp.privateKey; s.timestamp=Now(); auto sid=pqc::SecureRandom::Bytes(16); std::copy(sid.begin(),sid.end(),s.sessionId.begin()); return s;} Result<PQHandshakeState> PQHandshake::CreateServerHello(pqc::PQCryptoProvider& p,const std::vector<uint8_t>& cpk){ auto enc=p.Encapsulate(cpk); PQHandshakeState s; s.ephemeralKemPublicKey=cpk; s.ciphertext=enc.ciphertext; s.sharedSecret=pqc::SecureBuffer(enc.sharedSecret); s.sessionKey=pqc::SecureBuffer(Derive(enc.sharedSecret,cpk)); s.timestamp=Now(); return Result<PQHandshakeState>::Ok(std::move(s));} Result<void> PQHandshake::CompleteClient(PQHandshakeState& s,pqc::PQCryptoProvider& p,const std::vector<uint8_t>& ct){ s.ciphertext=ct; auto ss=p.Decapsulate(s.ephemeralKemPrivateKey,ct); s.sharedSecret=pqc::SecureBuffer(ss); s.sessionKey=pqc::SecureBuffer(Derive(ss,s.ephemeralKemPublicKey)); return Result<void>::Ok();} std::vector<uint8_t> PQHandshake::Confirm(const PQHandshakeState& s){ return pqc::Hashing::Kmac256(s.sessionKey.ToVectorCopy(),s.ciphertext,"PQC_P2P_CONFIRM_V1",32);} }
